template <int ID> struct Policy;

template <> struct Policy<1> {
    static constexpr int transform(int v) { return v + 10; }
};

template <> struct Policy<2> {
    static constexpr int transform(int v) { return v * 2; }
};

template <int ID, int Input>
constexpr int Execute() {
    return Policy<ID>::transform(Input);
}

// Compile-Time Polymorphism: Different execution paths selected
// and computed entirely by the compiler (Zero runtime overhead).
constexpr int R1 = Execute<1, 5>(); // Compiler computes 15
constexpr int R2 = Execute<2, 5>(); // Compiler computes 10
// The results are stored directly in data segments.
